"use client";

import SkeletonRow from "@/app/dashboard/admin/categories/SkeletonRow";
import { useSearchParams } from "next/navigation";
import { useCategories } from "@/hooks/useCategories";
import Image from "next/image";
import SearchBar from "@/components/common/SearchBar"

const CategoryTable = () => {
  const searchParams = useSearchParams();
  const currentPage = Number(searchParams.get("page")) || 1;
  const searchQuery = searchParams.get("search") || "";
  const pageSize = 10;

  const { data, isLoading, isError } = useCategories(currentPage, pageSize, searchQuery);

  return (
    <div>
      {/* Search Bar Component */}
      <SearchBar basePath="/dashboard/admin/categories" />

      {/* Table */}
      <table className="border-collapse border border-gray-300 w-full">
        <thead>
          <tr className="bg-gray-200">
            <th className="border p-2 text-gray-400">Category Picture</th>
            <th className="border p-2 text-gray-400">Category Name</th>
          </tr>
        </thead>
        <tbody>
          {isLoading
            ? Array.from({ length: 10 }).map((_, index) => <SkeletonRow key={index} />)
            : data?.content?.map((category) => (
                <tr key={category.categoryId}>
                  <td className="border p-2 text-gray-400">
                    <div className="w-[50px] h-[50px] flex items-center justify-center overflow-hidden rounded">
                      <Image
                        src={category.categoryPicture}
                        alt={category.categoryName}
                        width={50}
                        height={50}
                        className="rounded object-cover"
                        unoptimized
                      />
                    </div>
                  </td>
                  <td className="border p-2 text-gray-400">{category.categoryName}</td>
                </tr>
              ))}
        </tbody>
      </table>
    </div>
  );
};

export default CategoryTable;